-- ============================================================================
-- TradeQuote PRO: registry sync. Brings a database up to lib/modules.ts.
-- Generated by scripts/generate-migration.ts. Do not edit by hand.
--
-- Safe to run repeatedly, on a new database and on one that ran an older baseline.
-- It creates what is missing and rewrites every registry policy and trigger.
-- Hand-written rules belong in their own later migration.
-- ============================================================================

-- Company settings --------------------------------------------------------------
alter table public.companies add column if not exists overtime_multiplier numeric(5,2) not null default 1.5 check (overtime_multiplier between 1 and 10);
alter table public.companies add column if not exists default_holdback_pct numeric(5,2) not null default 10 check (default_holdback_pct between 0 and 100);
grant update (overtime_multiplier, default_holdback_pct) on public.companies to authenticated;

-- Module tables ---------------------------------------------------------------

-- Daily Logs (read 1, write 1, delete 3)
create table if not exists public.daily_logs (
  id uuid primary key default gen_random_uuid(),
  company_id uuid not null default public.user_company_id() references public.companies(id) on delete cascade,
  created_by uuid default auth.uid() references auth.users(id) on delete set null,
  title text not null check (char_length(title) between 1 and 300),
  status text not null,
  notes text,
  project_id uuid,
  log_date date,
  crew_lead text,
  weather text,
  crew_count numeric,
  hours numeric,
  work_done text,
  delays text,
  safety_notes text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.daily_logs add column if not exists project_id uuid;
alter table public.daily_logs add column if not exists log_date date;
alter table public.daily_logs add column if not exists crew_lead text;
alter table public.daily_logs add column if not exists weather text;
alter table public.daily_logs add column if not exists crew_count numeric;
alter table public.daily_logs add column if not exists hours numeric;
alter table public.daily_logs add column if not exists work_done text;
alter table public.daily_logs add column if not exists delays text;
alter table public.daily_logs add column if not exists safety_notes text;
create index if not exists daily_logs_company_idx on public.daily_logs(company_id, created_at desc);
drop trigger if exists daily_logs_updated on public.daily_logs;
create trigger daily_logs_updated before update on public.daily_logs for each row execute function public.set_updated_at();
alter table public.daily_logs enable row level security;
drop policy if exists daily_logs_select on public.daily_logs;
create policy daily_logs_select on public.daily_logs for select to authenticated
  using (company_id = public.user_company_id() and public.user_rank() >= 1);
drop policy if exists daily_logs_insert on public.daily_logs;
create policy daily_logs_insert on public.daily_logs for insert to authenticated
  with check (company_id = public.user_company_id() and public.user_rank() >= 1 and public.company_can_write() and created_by = auth.uid());
drop policy if exists daily_logs_update on public.daily_logs;
create policy daily_logs_update on public.daily_logs for update to authenticated
  using (company_id = public.user_company_id() and public.user_rank() >= 1 and public.company_can_write())
  with check (company_id = public.user_company_id());
drop policy if exists daily_logs_delete on public.daily_logs;
create policy daily_logs_delete on public.daily_logs for delete to authenticated
  using (company_id = public.user_company_id() and public.user_rank() >= 3 and public.company_can_write());
revoke all on public.daily_logs from anon;
grant select, insert, update, delete on public.daily_logs to authenticated;

