  company_id uuid not null default public.user_company_id() references public.companies(id) on delete cascade,
  created_by uuid default auth.uid() references auth.users(id) on delete set null,
  title text not null check (char_length(title) between 1 and 300),
  status text not null,
  notes text,
  project_id uuid,
  equipment_tag text,
  system_type text,
  created_at timestamptz not null default now(),
  updated_at timestamptz not null default now()
);
alter table public.commissioning add column if not exists project_id uuid;
alter table public.commissioning add column if not exists equipment_tag text;
alter table public.commissioning add column if not exists system_type text;
create index if not exists commissioning_company_idx on public.commissioning(company_id, created_at desc);
drop trigger if exists commissioning_updated on public.commissioning;
create trigger commissioning_updated before update on public.commissioning for each row execute function public.set_updated_at();
alter table public.commissioning enable row level security;
drop policy if exists commissioning_select on public.commissioning;
create policy commissioning_select on public.commissioning for select to authenticated
  using (company_id = public.user_company_id() and public.user_rank() >= 1);
drop policy if exists commissioning_insert on public.commissioning;
create policy commissioning_insert on public.commissioning for insert to authenticated
  with check (company_id = public.user_company_id() and public.user_rank() >= 2 and public.company_can_write() and created_by = auth.uid());
drop policy if exists commissioning_update on public.commissioning;
create policy commissioning_update on public.commissioning for update to authenticated
  using (company_id = public.user_company_id() and public.user_rank() >= 2 and public.company_can_write())
  with check (company_id = public.user_company_id());
drop policy if exists commissioning_delete on public.commissioning;
create policy commissioning_delete on public.commissioning for delete to authenticated
  using (company_id = public.user_company_id() and public.user_rank() >= 3 and public.company_can_write());
revoke all on public.commissioning from anon;
grant select, insert, update, delete on public.commissioning to authenticated;

