-- Link existing records by exact name -------------------------------------------
-- Only fills empty links, so running it again changes nothing that is already linked.
do $$
begin
  alter table public.timecards disable trigger user;
  update public.timecards r set project_id = x.id
    from public.projects x
    where r.project_id is null and x.company_id = r.company_id and x.title = r.title
      and not exists (select 1 from public.projects d where d.company_id = x.company_id and d.title = x.title and d.id <> x.id);
  alter table public.timecards enable trigger user;
  alter table public.punch_list disable trigger user;
  update public.punch_list r set project_id = x.id
    from public.projects x
    where r.project_id is null and x.company_id = r.company_id and x.title = r.project_name
      and not exists (select 1 from public.projects d where d.company_id = x.company_id and d.title = x.title and d.id <> x.id);
  alter table public.punch_list enable trigger user;
  alter table public.estimates disable trigger user;
  update public.estimates r set project_id = x.id
    from public.projects x
    where r.project_id is null and x.company_id = r.company_id and x.title = r.title
      and not exists (select 1 from public.projects d where d.company_id = x.company_id and d.title = x.title and d.id <> x.id);
  alter table public.estimates enable trigger user;
  alter table public.estimates disable trigger user;
  update public.estimates r set client_id = x.id
    from public.crm x
    where r.client_id is null and x.company_id = r.company_id and x.title = r.client_name
      and not exists (select 1 from public.crm d where d.company_id = x.company_id and d.title = x.title and d.id <> x.id);
  alter table public.estimates enable trigger user;
  alter table public.proposals disable trigger user;
  update public.proposals r set client_id = x.id
    from public.crm x
    where r.client_id is null and x.company_id = r.company_id and x.title = r.client_name
      and not exists (select 1 from public.crm d where d.company_id = x.company_id and d.title = x.title and d.id <> x.id);
  alter table public.proposals enable trigger user;
  alter table public.projects disable trigger user;
  update public.projects r set client_id = x.id
    from public.crm x
    where r.client_id is null and x.company_id = r.company_id and x.title = r.client_name
      and not exists (select 1 from public.crm d where d.company_id = x.company_id and d.title = x.title and d.id <> x.id);
  alter table public.projects enable trigger user;
  alter table public.change_orders disable trigger user;
  update public.change_orders r set project_id = x.id
    from public.projects x
    where r.project_id is null and x.company_id = r.company_id and x.title = r.project_name
      and not exists (select 1 from public.projects d where d.company_id = x.company_id and d.title = x.title and d.id <> x.id);
  alter table public.change_orders enable trigger user;
  alter table public.job_costing disable trigger user;
  update public.job_costing r set project_id = x.id
    from public.projects x
    where r.project_id is null and x.company_id = r.company_id and x.title = r.title
      and not exists (select 1 from public.projects d where d.company_id = x.company_id and d.title = x.title and d.id <> x.id);
  alter table public.job_costing enable trigger user;
  alter table public.invoices disable trigger user;
  update public.invoices r set client_id = x.id
    from public.crm x
    where r.client_id is null and x.company_id = r.company_id and x.title = r.client_name
      and not exists (select 1 from public.crm d where d.company_id = x.company_id and d.title = x.title and d.id <> x.id);
  alter table public.invoices enable trigger user;
  alter table public.purchase_orders disable trigger user;
  update public.purchase_orders r set project_id = x.id
    from public.projects x
    where r.project_id is null and x.company_id = r.company_id and x.title = r.project_name
      and not exists (select 1 from public.projects d where d.company_id = x.company_id and d.title = x.title and d.id <> x.id);
  alter table public.purchase_orders enable trigger user;
end $$;
